namespace ghidra.program.model.data;




using ghidra.docking.settings;
using ghidra.program.model.mem;
using ghidra.program.model.scalar;

/**
 * An abstract base class for a LEB128 variable length integer data type.
 * <p>
 * See {@link LEB128}.
 */
public abstract class AbstractLeb128DataType : BuiltIn, Dynamic {

	/* package */ static readonly FormatSettingsDefinition FORMAT = FormatSettingsDefinition.DEF_HEX;

	private static SettingsDefinition[] SETTINGS_DEFS = { FORMAT };

	private bool signed;

	/**
	 * Base constructor for a little endian based 128 data type.
	 * @param name name of the leb128 data type that extends this class.
	 * @param signed true if it is signed. false if unsigned.
	 * @param dtm the data type manager to associate with this data type.
	 */
	public AbstractLeb128DataType(string name, bool signed, DataTypeManager dtm) : base(null, name, dtm)
    {
		this.signed = signed;
	}

	/* @Override */
	protected SettingsDefinition[] getBuiltInSettingsDefinitions() {
		return SETTINGS_DEFS;
	}


	/* @Override */
	public int getLength() {
		return -1;
	}

	/* @Override */
	public int getLength(MemBuffer buf, int maxLength) {
		if (maxLength < 0) {
			maxLength = LEB128.MAX_SUPPORTED_LENGTH;
		}
		try
{
    using (InputStream @is = buf.getInputStream(0, maxLength))
    {

			return LEB128.getLength(@is);
		
    }
}
		catch (IOException e) {
			return -1;
		}
	}

	/* @Override */
	public Class<object> getValueClass(Settings settings) {
		return typeof(Scalar);
	}

	/* @Override */
	public object getValue(MemBuffer buf, Settings settings, int maxLength) {
		if (maxLength < 0) {
			maxLength = LEB128.MAX_SUPPORTED_LENGTH;
		}

		int len = getLength(buf, maxLength);
		if (len < 1) {
			return null; // error, or more than 10 bytes long
		}

		long val;
		try
{
    using (InputStream @is = buf.getInputStream(0, maxLength))
    {

			val = LEB128.read(@is, signed);
		
    }
}
		catch (IOException e) {
			return null;	// error, or more than 10 bytes long
		}

		// approximate bitLength from storage byte length
		int bitLength = Math.min(64, len * 7);
		int mod = bitLength % 8;
		if (mod != 0) {
			bitLength += (8 - mod);
		}

		return new Scalar(bitLength, val, signed);
	}

	/* @Override */
	public string getRepresentation(MemBuffer buf, Settings settings, int length) {

		Scalar val = (Scalar) getValue(buf, settings, length);
		if (val == null) {
			return "??";
		}

		int radix = FORMAT.getRadix(settings);
		string postfix = FORMAT.getRepresentationPostfix(settings);

		string valStr = val.toString(radix, false, signed, "", "");
		return valStr.toUpperCase() + postfix;
	}

	/* @Override */
	public DataType getReplacementBaseType() {
		return ByteDataType.dataType;
	}

	/* @Override */
	public bool canSpecifyLength() {
		return true;
	}

	/* @Override */
	public string getDefaultLabelPrefix() {
		return name;
	}

}
